#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# repo がまだ無い Mac でも動くよう、raw の URL から bash <(curl ...) で起動される前提。
# 各段は済んでいれば飛ばすので、途中で止めても頭から流し直せる。
REPO_URL=https://github.com/daiki-beppu/dotfiles.git
RAW_URL=https://raw.githubusercontent.com/daiki-beppu/dotfiles/main
REPO_DIR="$HOME/ghq/github.com/daiki-beppu/dotfiles"
NIX_PROFILE=/nix/var/nix/profiles/default/etc/profile.d/nix-daemon.sh

# Nix を入れた直後のこのシェルにも nix を通す。
load_nix() {
  if [[ -r "$NIX_PROFILE" ]]; then
    set +u
    # shellcheck disable=SC1090
    . "$NIX_PROFILE"
    set -u
  fi
}

# 初回の switch 後に入るコマンド（Nix・~/.local/bin・vp）をこのシェルにも通す。
load_dotfiles_path() {
  export PATH="/etc/profiles/per-user/$USER/bin:/run/current-system/sw/bin:$HOME/.local/bin:$HOME/.vite-plus/bin:/opt/homebrew/bin:$PATH"
}

# run_step "説明" cmd...: 失敗したら、やり直すか飛ばすかを選ばせる。
run_step() {
  local label="$1"; shift
  until "$@"; do
    warn "$label に失敗した"
    confirm "やり直す？（N で飛ばす）" || { SKIPPED+=("$label"); return 0; }
  done
}

# flake.nix の hosts から「ホスト名 ユーザー名」を 1 行ずつ出す。
list_hosts() {
  awk '
    /^ *hosts = \{/ { inside = 1; next }
    inside && /^ *\};/ && depth == 0 { exit }
    inside && /"[^"]+" = \{/ { match($0, /"[^"]+"/); host = substr($0, RSTART + 1, RLENGTH - 2); depth = 1; next }
    inside && depth && /username = "/ { match($0, /"[^"]+"/); print host, substr($0, RSTART + 1, RLENGTH - 2) }
    inside && depth && /\};/ { depth = 0 }
  '
}

banner "新しい Mac に dotfiles を適用する"

stage "適用するホストを決める"
if [[ -f "$REPO_DIR/flake.nix" ]]; then
  flake=$(cat "$REPO_DIR/flake.nix")
else
  flake=$(curl -fsSL "$RAW_URL/flake.nix")
fi
LOCAL_HOST=$(scutil --get LocalHostName 2>/dev/null || hostname -s)
say "この Mac: ユーザー名 $USER / ホスト名 $LOCAL_HOST"
candidates=()
while read -r host user; do
  [[ "$user" == "$USER" ]] && candidates+=("$host")
done < <(printf '%s\n' "$flake" | list_hosts)
if (( ${#candidates[@]} == 0 )); then
  warn "flake.nix の hosts に、ユーザー名 $USER のホストが無い"
  say "別の Mac で flake.nix の hosts に次を足して push し、このウィザードを流し直す:"
  printf '\n        "%s" = {\n          username = "%s";\n        };\n\n' "$LOCAL_HOST" "$USER"
  exit 1
fi
HOST="${candidates[0]}"
for h in "${candidates[@]}"; do [[ "$h" == "$LOCAL_HOST" ]] && HOST="$h"; done
if (( ${#candidates[@]} > 1 )); then
  note "候補: ${candidates[*]}"
  ask HOST_INPUT "使うホスト名（Enter で $HOST）:"
  [[ -n "$HOST_INPUT" ]] && HOST="$HOST_INPUT"
fi
printf '  %s✓%s .#%s を適用する\n' "$GREEN" "$RESET" "$HOST"
[[ "$HOST" != "$LOCAL_HOST" ]] && note "switch でホスト名は $HOST に変わる"
pause

stage "Xcode Command Line Tools を入れる"
if xcode-select -p >/dev/null 2>&1; then
  printf '  %s✓%s 入っている\n' "$GREEN" "$RESET"
else
  say "git などに必要。ダイアログが出るので「インストール」を押す。"
  xcode-select --install >/dev/null 2>&1 || true
  pause "インストールが終わったら Enter"
  xcode-select -p >/dev/null 2>&1 || { warn "まだ入っていない"; SKIPPED+=("Xcode Command Line Tools"); }
fi

stage "Determinate Nix を入れる"
load_nix
if command -v nix >/dev/null 2>&1; then
  printf '  %s✓%s 入っている: %s\n' "$GREEN" "$RESET" "$(nix --version)"
else
  say "インストーラが確認を求めるので、内容を見て進める。sudo のパスワードも聞かれる。"
  if confirm "Determinate Nix をインストールする？"; then
    run_step "Determinate Nix のインストール" \
      sh -c "curl --proto '=https' --tlsv1.2 -sSf -L https://install.determinate.systems/nix | sh -s -- install"
    load_nix
  else
    SKIPPED+=("Determinate Nix")
  fi
fi

stage "Homebrew を入れる"
if [[ -x /opt/homebrew/bin/brew ]]; then
  printf '  %s✓%s 入っている\n' "$GREEN" "$RESET"
else
  say "nix-darwin は Homebrew 自体は入れないので、cask を扱う前に入れておく。"
  if confirm "Homebrew をインストールする？"; then
    run_step "Homebrew のインストール" \
      /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"
  else
    SKIPPED+=("Homebrew")
  fi
fi

stage "App Store にサインインする"
say "flake の masApps（Klack など）を入れるのに、App Store のサインインが要る。"
open -a "App Store" >/dev/null 2>&1 || warn "App Store を開けなかった。手で開く"
step "メニューの「ストア」→「サインイン」で Apple ID にサインインする"
note "サインイン済みならそのまま Enter"
pause "サインインしたら Enter"

stage "dotfiles をクローンする"
if [[ -d "$REPO_DIR/.git" ]]; then
  printf '  %s✓%s クローン済み: %s\n' "$GREEN" "$RESET" "$REPO_DIR"
else
  run_step "dotfiles のクローン" nix run nixpkgs#ghq -- get "$REPO_URL"
fi
if [[ -L "$HOME/.dotfiles" || ! -e "$HOME/.dotfiles" ]]; then
  ln -sfn "$REPO_DIR" "$HOME/.dotfiles"
  printf '  %s✓%s ~/.dotfiles → %s\n' "$GREEN" "$RESET" "$REPO_DIR"
else
  warn "$HOME/.dotfiles が symlink ではないので触らなかった"
  SKIPPED+=("$HOME/.dotfiles の symlink")
fi
pause

stage "nix-darwin で初回の switch をする"
say "nix-darwin・Home Manager・Homebrew cask をまとめて適用する。時間がかかる。"
note "/etc の既存ファイルで止まったら、表示された mv を別のターミナルで流してからやり直す"
if confirm "sudo で .#$HOST を switch する？"; then
  if command -v darwin-rebuild >/dev/null 2>&1; then
    run_step "初回の switch" sudo darwin-rebuild switch --flake "$REPO_DIR#$HOST"
  else
    run_step "初回の switch" sudo nix run nix-darwin -- switch --flake "$REPO_DIR#$HOST"
  fi
else
  SKIPPED+=("初回の switch: sudo nix run nix-darwin -- switch --flake $REPO_DIR#$HOST")
fi
load_dotfiles_path

stage "ディスプレイの解像度を変える"
open "x-apple.systempreferences:com.apple.Displays-Settings.extension" >/dev/null 2>&1 \
  || warn "システム設定を開けなかった。手で「ディスプレイ」を開く"
step "「スペースを拡大」を選ぶ"
pause "変えたら Enter"

stage "アプリの初期設定をする"
for app in "1Password" "Google Drive" "Cap"; do
  open -a "$app" >/dev/null 2>&1 || warn "$app を開けなかった"
done
step "1Password: アカウントでサインインする"
step "Google Drive: ログインして同期フォルダを設定する"
step "Cap: 画面収録の権限を許可し、ショートカットを設定する（クラウド共有を使うならサインイン）"
pause "済んだら Enter"

stage "takt の provider と MCP を用意する"
if command -v takt >/dev/null 2>&1; then
  run_step "takt install claude-sdk" takt install claude-sdk
  run_step "takt install codex" takt install codex
else
  warn "takt が無い。初回の switch が済んでいるか確かめる"
  SKIPPED+=("takt install claude-sdk / codex")
fi
if command -v claude >/dev/null 2>&1; then
  claude mcp get takt >/dev/null 2>&1 \
    || run_step "Claude Code への takt MCP の登録" claude mcp add --scope user takt -- "$HOME/.local/bin/takt-mcp-root"
else
  SKIPPED+=("Claude Code を入れて: claude mcp add --scope user takt -- ~/.local/bin/takt-mcp-root")
fi
if command -v codex >/dev/null 2>&1; then
  codex mcp get takt >/dev/null 2>&1 \
    || run_step "Codex への takt MCP の登録" codex mcp add takt -- "$HOME/.local/bin/takt-mcp-root"
else
  SKIPPED+=("codex mcp add takt -- ~/.local/bin/takt-mcp-root")
fi
pause

stage "確認する"
if command -v vp >/dev/null 2>&1; then
  printf '  %s✓%s vp: %s\n' "$GREEN" "$RESET" "$(vp --version 2>/dev/null | head -1)"
else
  warn "vp が見つからない。新しいシェルで command -v vp を確かめる"
  SKIPPED+=("vp の確認")
fi
say "設定を読み込むため、ターミナル（起動中の Codex なども）を開き直す。"
note "2 回目以降の適用: sudo darwin-rebuild switch --flake $REPO_DIR"
pause "Enter で終わる"

finish
